insert into public.challenges (
  id, module_id, slug, title, scenario, learner_goal, instructions,
  repo_template_url, repo_branch, validation_config_json, ai_rules_json,
  skills, is_free, order_index
) values (
  '00000000-0000-0000-0000-00000000031d',
  '00000000-0000-0000-0000-000000000033',
  'quant-30-binomial-tree-pricer',
  E'Binomial tree pricer',
  E'Before Black-Scholes'' PDE became standard in vol-desk software, the CRR (Cox-Ross-Rubinstein) tree was *the* pricing algorithm. It still is for American options — early exercise needs a backward induction that the closed-form BS can''t do. Every Hull chapter on exotic options starts here; every options engineer can sketch the recurrence on a whiteboard.',
  E'Price a European call with a 50-step binomial tree.',
  E'**Concept.** Set `u = exp(σ·√dt)`, `d = 1/u` (Cox-Ross-Rubinstein parameterisation, multiplicatively symmetric). Risk-neutral up-probability `p = (exp(r·dt) − d) / (u − d)`. Build terminal payoffs at expiry, then walk back to t=0: at each node, value = `exp(−r·dt) · (p·V_up + (1−p)·V_down)`. As N → ∞ the price converges to Black-Scholes.\n\n**Example.**\n\n```python\nimport numpy as np\n# 50-step CRR tree on Hull''s BS example.\nS, K, r, sigma, T, N = 100, 100, 0.05, 0.20, 1.0, 50\n# Up/down factors and risk-neutral probability.\ndt = T/N; u = np.exp(sigma*np.sqrt(dt)); d = 1/u\np = (np.exp(r*dt) - d)/(u - d)\n# Terminal prices at expiry: S * u^i * d^(N-i) for i = 0..N.\nST = S * u**np.arange(N+1) * d**(N - np.arange(N+1))\nvals = np.maximum(ST - K, 0)\n# Backward induction — discount + risk-neutral average at each step.\nfor _ in range(N):\n    vals = np.exp(-r*dt) * (p*vals[1:] + (1-p)*vals[:-1])\n# vals[0] is t=0. Compare to BS 10.4506 — convergence is monotonic in N.\nprint(round(vals[0], 4))\n```\n\n**Your turn.** Replace `___` with the slice that gives ''all but the last'' (the down-branch values).\n\n**Expected.** `10.4107`',
  null,
  null,
  '{}',
  '{"max_hint_level": 2, "do_not_reveal_solution": false, "encourage_tests_first": false}',
  array['quant', 'options', 'black-scholes'],
  true,
  30
)
